    <div class='"'"'form'"'"' id='"'"'form'"'"' style='"'"'display: none;'"'"'>
      <input type='"'"'number'"'"' id='"'"'answer'"'"' placeholder='"'"'Enter the product'"'"'>
      <button onclick='"'"'checkAnswer()'"'"'>Submit</button>
    </div>
    <div id='"'"'result'"'"'></div>
  </div>
  <script>
    class SeededRNG {
      constructor(seed) { this.seed = seed; }
      random() {
        const a=1664525,c=1013904223,m=2**32;
        this.seed=(a*this.seed+c)%m;
        return this.seed/m;
      }
    }
    const rng=new SeededRNG(1104996223);
    const numbers=[];
    let clickCount=0;
    function generateNumber(){
      const number=Math.floor(rng.random()*10)+1;
      numbers.push(number);
      document.getElementById('"'"'number'"'"').textContent=number;
    }
    function handleButtonClick(){
      clickCount++;
      if(clickCount<5){generateNumber();}
      else{
        document.getElementById('"'"'button'"'"').style.display='"'"'none'"'"';
        document.getElementById('"'"'number'"'"').style.display='"'"'none'"'"';
        document.getElementById('"'"'form'"'"').style.display='"'"'block'"'"';
      }
    }
    function checkAnswer(){
      const answer=parseInt(document.getElementById('"'"'answer'"'"').value);
      const product=numbers.reduce((acc,num)=>acc*num,1);
      const result=document.getElementById('"'"'result'"'"');
      if(answer===product){result.innerHTML='"'"'<h2>Success!</h2>'"'"';}
      else{result.innerHTML='"'"'<h2></h2>'"'"';}
    }
    generateNumber();
    setTimeout(function(){
      for(let i=0;i<5;i++) handleButtonClick();
      const product=numbers.reduce((acc,num)=>acc*num,1);
      document.getElementById('"'"'answer'"'"').value=product;
      checkAnswer();
    },300);
  </script>
</body>
</html>
